#include<bits/stdc++.h>
#define int long long
using namespace std;
int a[222222],f[222222],g[222222];
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n,m;
	cin>>n>>m;
	for(int i=1;i<=n;i++){
		cin>>a[i];
	}
	for(int i=1;i<=n;i++){
		a[n+i]=a[i];
	}
	int l=1,r=1,c=1;
	g[a[1]]++;
	while(l<=2*n){
		if(c==m){
			f[l]=r;
			g[a[l]]--;
			if(g[a[l]]==0){
				c--;
			}
			l++;
		}else{
			if(r==2*n){
				break;
			}
			r++;
			g[a[r]]++;
			if(g[a[r]]==1){
				c++;
			}
		}
	}
	int ans=0;
	for(int i=1;i<=n;i++){
		int cnt=0;
		int j=i;
		while(j<=2*n&&f[j]!=0&&f[j]<i+n){
			cnt++;
			j=f[j]+1;
//			cout<<j<<endl;
		}
		ans=max(ans,cnt);
	}
	cout<<ans;
    return 0;
}
